import{_ as t,o,c as s,ah as a}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Comptes et accès","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/accounts.md","filePath":"src/guide/administration/accounts.md"}'),n={name:"guide/administration/accounts.md"};function r(i,e,c,u,p,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="comptes-et-acces" tabindex="-1">Comptes et accès <a class="header-anchor" href="#comptes-et-acces" aria-label="Permalink to &quot;Comptes et accès&quot;">​</a></h1><p><strong>Administration → Comptes</strong> est réservé au PDG. <strong>Administration → Départs</strong> est ouvert au PDG et au volet RH &amp; Affaires Juridiques.</p><h2 id="la-liste-des-comptes" tabindex="-1">La liste des comptes <a class="header-anchor" href="#la-liste-des-comptes" aria-label="Permalink to &quot;La liste des comptes&quot;">​</a></h2><p>Elle montre, pour chaque personne, son poste, son département, son statut et l&#39;état de son invitation (<strong>Invitation en attente</strong>, <strong>Invitation expirée</strong>, <strong>Activé</strong>). Recherchez par nom ou e-mail, filtrez par poste ou statut, et <strong>Exporter en CSV</strong> pour obtenir la liste filtrée.</p><h2 id="inviter-une-personne" tabindex="-1">Inviter une personne <a class="header-anchor" href="#inviter-une-personne" aria-label="Permalink to &quot;Inviter une personne&quot;">​</a></h2><ol><li><strong>Nouveau compte</strong>.</li><li><strong>Identité</strong> : nom, e-mail (l&#39;adresse où partira l&#39;invitation), langue de l&#39;invitation et de l&#39;interface, et, si besoin, <strong>Exiger l&#39;authentification à deux facteurs</strong> pour ce compte.</li><li><strong>Poste</strong> et <strong>département</strong> (facultatif).</li><li><strong>Périmètre</strong>, selon le poste : <ul><li>Support N1 et N2 : produits, zones et bureaux sur lesquels la personne travaille, avec au moins un produit ;</li><li>PDG et pôles : tous les produits et toutes les zones, rien à choisir ;</li><li>RH et Finance : transverses, sans produit ni zone.</li></ul></li><li><strong>Accès aux back-offices produits</strong> : cochez les produits dont la personne pourra ouvrir le back-office (voir ci-dessous).</li><li><strong>Créer le compte</strong>.</li></ol><p>L&#39;e-mail d&#39;invitation part aussitôt, avec un mot de passe temporaire valable pendant la durée fixée dans la <a href="./settings.html">configuration</a> (7 jours par défaut). La personne choisit son propre mot de passe à la première connexion.</p><h3 id="renvoyer-une-invitation" tabindex="-1">Renvoyer une invitation <a class="header-anchor" href="#renvoyer-une-invitation" aria-label="Permalink to &quot;Renvoyer une invitation&quot;">​</a></h3><p>Une invitation expirée n&#39;est jamais renouvelée automatiquement. Sur la fiche du compte, <strong>Envoyer une nouvelle invitation</strong> envoie un nouveau mot de passe temporaire ; l&#39;ancien ne fonctionne plus.</p><h2 id="modifier-un-poste-un-perimetre-ou-des-acces" tabindex="-1">Modifier un poste, un périmètre ou des accès <a class="header-anchor" href="#modifier-un-poste-un-perimetre-ou-des-acces" aria-label="Permalink to &quot;Modifier un poste, un périmètre ou des accès&quot;">​</a></h2><p>Ouvrez le compte, modifiez, puis enregistrez. Le changement s&#39;applique à la requête suivante de la personne, sans reconnexion. Elle en est prévenue (notification « Vos accès »).</p><p>Si vous modifiez votre propre compte, changer de poste peut vous retirer l&#39;accès à cette page.</p><h2 id="acces-aux-back-offices-produits" tabindex="-1">Accès aux back-offices produits <a class="header-anchor" href="#acces-aux-back-offices-produits" aria-label="Permalink to &quot;Accès aux back-offices produits&quot;">​</a></h2><p>Le SSO n&#39;ouvre <strong>aucun</strong> back-office par défaut. Une personne ouvre le back-office d&#39;un produit :</p><ul><li>si l&#39;accès lui est accordé sur sa fiche, compte par compte, quel que soit son périmètre ;</li><li>ou si elle est membre d&#39;une <a href="./teams.html">équipe</a> responsable du produit.</li></ul><p>La fiche montre à part les accès venus d&#39;une équipe (« Par une équipe : … »). Retirer un accès accordé laisse ouvert un produit que la personne garde par une équipe. Quand une personne perd son dernier accès à un produit, ses sessions et ses jetons pour ce back-office sont révoqués immédiatement.</p><p>Ce que la personne peut faire <strong>dans</strong> le back-office dépend de son poste : pour Auticway, voir <a href="./../auticway.html">Back-office Auticway</a>.</p><h2 id="desactiver-un-compte" tabindex="-1">Désactiver un compte <a class="header-anchor" href="#desactiver-un-compte" aria-label="Permalink to &quot;Désactiver un compte&quot;">​</a></h2><p>Un compte n&#39;est jamais supprimé : il est désactivé.</p><ol><li><strong>Départs</strong> (ou <strong>Désactiver</strong> dans la liste des comptes).</li><li>Recherchez la personne, puis <strong>Désactiver</strong> et confirmez.</li></ol><p>La personne est déconnectée partout immédiatement, M&#39;City IQ et back-offices produits compris, et ses accès aux back-offices sont retirés. Le compte et son historique sont conservés.</p><p>Personne ne peut désactiver son propre compte, et le dernier compte PDG actif ne peut pas être désactivé.</p><h3 id="reactiver-un-compte" tabindex="-1">Réactiver un compte <a class="header-anchor" href="#reactiver-un-compte" aria-label="Permalink to &quot;Réactiver un compte&quot;">​</a></h3><p>Le PDG peut <strong>Réactiver</strong> un compte désactivé. La personne peut de nouveau se connecter, mais ses accès aux back-offices produits ne sont pas rétablis : accordez-les de nouveau depuis sa fiche.</p>',24)])])}const f=t(n,[["render",r]]);export{m as __pageData,f as default};
